body {
    color: #5D5F63;
    background: #212121;
    font-family: 'Open Sans', sans-serif;
    padding: 0px;
    margin: 0px;
    line-height: 1;
    text-rendering: optimizeLegibility;
    -webkit-font-smoothing: antialiased;
}

a:link,
a:visited {
    text-decoration: none;
    outline: none;
    /* color: #e84c3d; */
}

a:hover,
a:active {
    outline: none;
    text-decoration: none;
    color: #16a086;
}

h1,
h2,
h3,
h4,
h5,
h6 {
    font-family: 'Source Sans Pro', Arial, sans-serif;
}

p {
    font-size: 14px;
}

hr {
    margin-top: 10px;
    margin-bottom: 10px;
}

img {
    max-width: 100%;
}

::selection {
    background: #fff7dd;
}

::-moz-selection {
    background: #fff7dd;
}

/* ==========================================================================
   Layout
